//! shadcn-svelte components, as generated by its CLI, running in the host.
//! `examples/shadcn` uses the ones that work; this drives that page.
//!
//! Build the bundle first: `pnpm run build` in the repository root.

use std::path::Path;

use svelte_blitz_host::SvelteDocument;
use svelte_blitz_host::app::App;

fn load() -> SvelteDocument {
    let dist = Path::new(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../examples/shadcn/dist"
    ));
    let app = App::from_dir(dist).expect("run `pnpm run build` in the repository root first");
    let mut doc = SvelteDocument::for_app(&app).unwrap();
    doc.layout(900, 700);
    doc
}

fn text(doc: &SvelteDocument, selector: &str) -> String {
    doc.text(doc.query(selector).unwrap())
}

fn attr(doc: &SvelteDocument, selector: &str, name: &str) -> Option<String> {
    doc.attr(doc.query(selector).unwrap(), name)
}

fn click(doc: &mut SvelteDocument, selector: &str) {
    let node = doc
        .query(selector)
        .unwrap_or_else(|| panic!("nothing matches {selector}"));
    doc.click(node);
    doc.settle();
    doc.resolve();
}

#[test]
fn shadcn_components_render_and_react() {
    let mut doc = load();

    // Every shadcn component has `bind:this={ref}` on its root element, which
    // Svelte refuses for a custom renderer. The preset rewrites it; the page
    // binds a Button's ref and reports whether a node arrived.
    assert_eq!(text(&doc, "#ref"), "ref bound");

    // The components carry shadcn's classes and data attributes, and its theme applies.
    let button = doc.query("#count").unwrap();
    assert_eq!(doc.attr(button, "data-slot").as_deref(), Some("button"));
    let (_, _, width, height) = doc.rect(button).unwrap();
    assert!(
        width > 60.0 && height >= 28.0,
        "the button is styled: {width}x{height}"
    );
    assert!(
        doc.query("[data-slot=card] [data-slot=card-title]")
            .is_some()
    );
    assert!(
        doc.query("[data-slot=progress]").is_some(),
        "a Bits UI primitive mounted"
    );

    // Events pass through the component's `{...restProps}` to the element.
    doc.click(button);
    doc.click(button);
    assert_eq!(text(&doc, "#count"), "Clicked 2");
    assert_eq!(text(&doc, "[data-slot=badge]:nth-of-type(2)"), "2 clicks");

    // `bind:value` on the Input's <input>: the value reaches the element.
    assert_eq!(
        doc.attr(doc.query("#name").unwrap(), "value").as_deref(),
        Some("Ada")
    );
    assert_eq!(text(&doc, "#greeting"), "Hello, Ada.");

    // The Progress bar is empty: its indicator is moved out of view with a
    // percentage transform, which Blitz works out once, at the first layout.
    // (Laying out before the window had a size left it covering the bar.)
    let bar = doc
        .rect(doc.query("[data-slot=progress]").unwrap())
        .unwrap();
    let (pixels, width, _) = svelte_blitz_host::screenshot::render_rgba(&mut doc, 900, 700, 1.0);
    let at = ((bar.1 + bar.3 / 2.0) as usize * width as usize + (bar.0 + bar.2 / 2.0) as usize) * 4;
    assert!(pixels[at] > 200, "an empty bar is light: {}", pixels[at]);
}

/// The components built on Bits UI, which is written for a browser. They run
/// on the DOM layer that `dom: true` in app.config.ts loads.
#[test]
fn bits_ui_components_work_on_the_dom_layer() {
    let mut doc = load();

    // `bind:checked` passes through two components that both spread their
    // props. Svelte finds the setter by asking a Proxy for a property
    // descriptor, which QuickJS answers wrongly without the fix in shims.js.
    assert_eq!(text(&doc, "#switch-state"), "Switch is off");
    click(&mut doc, "#switch");
    assert_eq!(text(&doc, "#switch-state"), "Switch is on");
    assert_eq!(
        attr(&doc, "#switch", "data-state").as_deref(),
        Some("checked")
    );
    click(&mut doc, "#switch");
    assert_eq!(text(&doc, "#switch-state"), "Switch is off");

    click(&mut doc, "#check");
    assert_eq!(text(&doc, "#check-state"), "Checked");
    assert_eq!(
        attr(&doc, "#check", "aria-checked").as_deref(),
        Some("true")
    );

    // Tabs: both panels exist and one is hidden. A click swaps which, and the
    // triggers swap state.
    assert_eq!(
        text(&doc, "[data-tabs-content]:not([hidden]) .tab-panel"),
        "Account panel"
    );
    click(&mut doc, "[data-tabs-trigger][data-value=password]");
    assert_eq!(
        text(&doc, "[data-tabs-content]:not([hidden]) .tab-panel"),
        "Password panel"
    );
    assert_eq!(
        attr(
            &doc,
            "[data-tabs-trigger][data-value=password]",
            "data-state"
        )
        .as_deref(),
        Some("active")
    );
    assert_eq!(
        attr(
            &doc,
            "[data-tabs-trigger][data-value=account]",
            "data-state"
        )
        .as_deref(),
        Some("inactive")
    );

    // Accordion: closed content takes no room; open content does, once the
    // opening animation is over.
    let height = |doc: &SvelteDocument| doc.query("#answer").and_then(|n| doc.rect(n)).map(|r| r.3);
    assert!(height(&doc).is_none_or(|h| h == 0.0), "closed at first");
    click(&mut doc, "[data-accordion-trigger]");
    assert_eq!(
        attr(&doc, "[data-accordion-trigger]", "aria-expanded").as_deref(),
        Some("true")
    );
    doc.wait(0.4);
    assert!(
        height(&doc).is_some_and(|h| h > 10.0),
        "open: {:?}",
        height(&doc)
    );
}

/// A Dialog is mounted into `document.body`, dims the page behind it, and is
/// dismissed by a click outside, which Bits UI detects with capture listeners
/// on `document`.
#[test]
fn a_dialog_opens_over_the_page_and_closes() {
    let mut doc = load();
    let pixel = |doc: &mut SvelteDocument, x: usize, y: usize| {
        let (pixels, width, _) = svelte_blitz_host::screenshot::render_rgba(doc, 900, 700, 1.0);
        let at = (y * width as usize + x) * 4;
        [pixels[at], pixels[at + 1], pixels[at + 2]]
    };
    assert!(doc.query("[role=dialog]").is_none());
    assert_eq!(pixel(&mut doc, 5, 5), [255, 255, 255]);

    click(&mut doc, "#open-dialog");
    // Past the fade-in.
    doc.wait(0.3);
    assert_eq!(
        text(&doc, "[role=dialog] [data-slot=dialog-title]"),
        "Are you sure?"
    );
    let dimmed = pixel(&mut doc, 5, 5);
    assert!(dimmed[0] < 245, "the overlay dims the page: {dimmed:?}");
    // The box itself is in the middle of the window; this is its left padding.
    assert_eq!(pixel(&mut doc, 240, 350), [255, 255, 255]);

    doc.click_at(5.0, 690.0);
    // Past the fade-out, and the timer that unlocks scrolling after it.
    doc.wait(0.4);
    assert!(doc.query("[role=dialog]").is_none(), "closed");
    assert_eq!(pixel(&mut doc, 5, 5), [255, 255, 255]);
    assert_eq!(attr(&doc, "body", "style"), None, "scrolling is unlocked");
}

/// Where a popup was put: the `translate(x, y)` on the box Floating UI
/// positions. Blitz's own boxes (`doc.rect`) are from before transforms.
fn placed_at(doc: &SvelteDocument) -> (f64, f64) {
    let style = attr(doc, "[data-bits-floating-content-wrapper]", "style").unwrap();
    let inner = style
        .split_once("translate(")
        .and_then(|(_, rest)| rest.split_once(')'))
        .unwrap_or_else(|| panic!("no translate in {style}"))
        .0;
    let (x, y) = inner.split_once(',').unwrap();
    let px = |value: &str| value.trim().trim_end_matches("px").parse::<f64>().unwrap();
    (px(x), px(y))
}

/// A Select places its list with Floating UI, which measures the trigger and
/// the window. JavaScript cannot ask the host for that; the host reports it
/// after each layout, and the list has moved before the frame is drawn.
#[test]
fn a_select_opens_under_its_trigger_and_picks() {
    let mut doc = load();
    let (left, top, width, height) = doc.rect(doc.query("#fruit").unwrap()).unwrap();
    assert_eq!(text(&doc, "#fruit"), "apple");

    click(&mut doc, "#fruit");
    // No waiting: one turn is enough to measure and to move.
    let (x, y) = placed_at(&doc);
    assert!(
        (0.0..12.0).contains(&(y - (top + height))),
        "just under the trigger, which ends at {}: {y}",
        top + height
    );
    assert!(
        (x - left).abs() < width / 2.0,
        "and lined up with it, at {left}: {x}"
    );

    // The list is as wide as its trigger: its size came from a measurement too.
    let list = doc
        .rect(doc.query("[data-select-content]").unwrap())
        .unwrap();
    assert_eq!(list.2, width);

    // Pick the second item. Its own box is relative to the popup.
    doc.wait(0.2);
    let item = doc
        .rect(doc.query("[data-select-item][data-value=banana]").unwrap())
        .unwrap();
    doc.click_at(
        (x + item.0 + item.2 / 2.0) as f32,
        (y + item.1 + item.3 / 2.0) as f32,
    );
    doc.wait(0.4);
    assert_eq!(text(&doc, "#fruit"), "banana");
    assert!(doc.query("[data-select-content]").is_none(), "closed");

    // While it is open the page ignores the pointer (`pointer-events: none`
    // on <body>), so a click outside lands on <html>. It still closes the list.
    click(&mut doc, "#fruit");
    doc.wait(0.2);
    doc.click_at(880.0, 20.0);
    doc.wait(0.4);
    assert!(doc.query("[data-select-content]").is_none(), "dismissed");
    assert_eq!(attr(&doc, "body", "style"), None);
}

#[test]
fn a_tooltip_appears_over_what_the_pointer_is_on() {
    let mut doc = load();
    let (left, top, width, height) = doc.rect(doc.query("#tip").unwrap()).unwrap();
    assert!(doc.query("[data-tooltip-content]").is_none());

    doc.move_to(5.0, 5.0);
    doc.move_to((left + width / 2.0) as f32, (top + height / 2.0) as f32);
    doc.wait(0.3);
    let tip = doc
        .rect(
            doc.query("[data-tooltip-content]")
                .expect("the tooltip opened"),
        )
        .unwrap();
    let (x, y) = placed_at(&doc);
    let gap = top - (y + tip.3);
    // The gap holds the tooltip's arrow.
    assert!((0.0..=20.0).contains(&gap), "just above the trigger: {gap}");
    let off_centre = (x + tip.2 / 2.0) - (left + width / 2.0);
    assert!(off_centre.abs() < 2.0, "centred on it: {off_centre}");

    doc.move_to(700.0, 650.0);
    doc.wait(0.4);
    assert!(doc.query("[data-tooltip-content]").is_none(), "gone");
}

/// What JavaScript knows about layout is what the host last reported.
#[test]
fn measurements_come_from_the_last_layout() {
    let mut doc = load();
    let eval = |doc: &SvelteDocument, code: &str| doc.js().eval_string(code).unwrap();
    assert_eq!(eval(&doc, "innerWidth + 'x' + innerHeight"), "900x700");

    // Never measured before: the answer is empty, and asking is what makes
    // the host report this node from the next layout on.
    let measure = "(() => { const r = document.getElementById('count').getBoundingClientRect(); return [r.x, r.y, r.width, r.height].join() })()";
    assert_eq!(eval(&doc, measure), "0,0,0,0");
    doc.settle();
    doc.resolve();
    let (x, y, width, height) = doc.rect(doc.query("#count").unwrap()).unwrap();
    assert_eq!(eval(&doc, measure), format!("{x},{y},{width},{height}"));

    // A resize reaches the app as new sizes and a `resize` event.
    eval(
        &doc,
        "globalThis.resizes = 0; addEventListener('resize', () => resizes++); ''",
    );
    doc.layout(600, 500);
    assert_eq!(
        eval(&doc, "[innerWidth, innerHeight, resizes].join()"),
        "600,500,1"
    );

    // Nothing moved, so an idle turn tells the app nothing and changes nothing.
    assert_eq!(doc.settle().ops, 0);
    assert_eq!(eval(&doc, "String(resizes)"), "1");
}

/// Blitz used to hit-test a box that sits in a line of text as if it were
/// shifted by its container's padding (see crates/blitz-dom/PATCH.md).
#[test]
fn a_button_in_a_line_of_text_is_clicked_where_it_is_drawn() {
    let mut doc = load();
    // Just inside its top left corner: the middle of a button this size is
    // still inside the shifted box.
    let (x, y, ..) = doc.rect(doc.query("#inline").unwrap()).unwrap();
    doc.click_at(x as f32 + 3.0, y as f32 + 3.0);
    doc.settle();
    doc.resolve();
    assert_eq!(text(&doc, "#count"), "Clicked 1");
}
